create table public.workers(
"id" uuid not null default gen_random_uuid(),
"user_id" uuid,
"email" text,
"display_name" text,
"role" text not null,
"team" text,
"shift_start_hour" integer,
"shift_length_hours" integer,
"state" text not null default 'offline'::text,
"salary_base" numeric not null default 0,
"is_active" boolean not null default true,
"created_at" timestamp with time zone not null default now(),
"call_key" text,
"shift_type" text,
"tarotista_level" smallint not null default 1,
"auth_user_id" uuid,
UNIQUE (email),
PRIMARY KEY (id),
CHECK ((role = ANY (ARRAY['admin'::text, 'central'::text, 'tarotista'::text]))),
CHECK ((state = ANY (ARRAY['online'::text, 'offline'::text, 'pause'::text, 'bathroom'::text]))),
CHECK ((tarotista_level = ANY (ARRAY[1, 2]))),
CHECK (((team IS NULL) OR (team = ANY (ARRAY['fuego'::text, 'agua'::text, 'tierra'::text])))),
UNIQUE (user_id)
);

