CHECK (((ends_at IS NULL) OR (ends_at > starts_at))),
CHECK (((automatic_rank_at_creation IS NULL) OR (automatic_rank_at_creation = ANY (ARRAY['bronce'::text, 'plata'::text, 'oro'::text])))),
CHECK ((intervention_type = ANY (ARRAY['temporary'::text, 'permanent'::text, 'penalty'::text]))),
PRIMARY KEY (id),
CHECK (((previous_effective_rank IS NULL) OR (previous_effective_rank = ANY (ARRAY['bronce'::text, 'plata'::text, 'oro'::text])))),
