"rarity" text not null default 'common'::text,
"weight" numeric(12,4) not null default 1,
"special" boolean not null default false,
"fulfillment_mode" text not null default 'immediate'::text,
"icon_key" text,
"metadata" jsonb not null default '{}'::jsonb,
"is_active" boolean not null default true,
"sort_order" integer not null default 0,
"created_at" timestamp with time zone not null default now(),
"updated_at" timestamp with time zone not null default now(),
CHECK ((fulfillment_mode = ANY (ARRAY['immediate'::text, 'temporary'::text, 'manual'::text, 'claim'::text, 'scheduled'::text]))),
PRIMARY KEY (id),
CHECK ((rarity = ANY (ARRAY['common'::text, 'uncommon'::text, 'rare'::text, 'epic'::text, 'legendary'::text, 'ultra'::text, 'diamond'::text, 'jackpot'::text]))),
CHECK ((weight >= (0)::numeric)),
CHECK (((nivel >= 1) AND (nivel <= 5))),
CHECK ((reward_type = ANY (ARRAY['minutes'::text, 'coins'::text, 'oracle_credits'::text, 'rank'::text, 'ritual'::text, 'streak_minutes'::text, 'perk'::text])))
);

