PRIMARY KEY (id),
CHECK ((status = ANY (ARRAY['pending'::text, 'active'::text, 'completed'::text, 'expired'::text, 'cancelled'::text])))
);

create table public.client_benefit_rules(
"id" uuid not null default gen_random_uuid(),
"name" text not null,
"description" text not null default ''::text,
"rank" text,
"event" text not null default 'purchase'::text,
"claim_mode" text not null default 'automatic'::text,
"scope" text not null default 'regular'::text,
"currency" text not null default 'EUR'::text,
"min_amount" numeric not null default 0,
"max_amount" numeric,
"mode" text not null default 'add'::text,
"coins" integer,
"coins_rate" numeric,
"free_minutes" integer,
"oracle_credits" integer,
"roulette_spins" integer,
"roulette_level" smallint,
"priority" integer not null default 0,
"sort_order" integer not null default 0,
"active" boolean not null default false,
"starts_at" timestamp with time zone not null default now(),
"ends_at" timestamp with time zone,
"archived_at" timestamp with time zone,
"revision" integer not null default 1,
"created_at" timestamp with time zone not null default now(),
"updated_at" timestamp with time zone not null default now(),
CHECK ((max_amount > min_amount)),
CHECK (((ends_at IS NULL) OR (ends_at > starts_at))),
CHECK (((coins IS NULL) OR (coins_rate IS NULL))),
CHECK (((roulette_spins IS NULL) OR (roulette_level IS NOT NULL))),
CHECK (((event = 'purchase'::text) OR ((rank IS NOT NULL) AND (coins_rate IS NULL) AND (mode = 'add'::text)))),
CHECK (((event <> 'purchase'::text) OR (claim_mode = 'automatic'::text))),
CHECK (((event = 'information'::text) OR (num_nonnulls(coins, coins_rate, free_minutes, oracle_credits, roulette_spins) > 0))),
CHECK ((claim_mode = ANY (ARRAY['automatic'::text, 'claim'::text]))),
CHECK (((coins >= 0) AND (coins <= 1000000))),
CHECK (((coins_rate >= (0)::numeric) AND (coins_rate <= (1000)::numeric))),
CHECK ((currency = ANY (ARRAY['EUR'::text, 'USD'::text]))),
CHECK ((event = ANY (ARRAY['purchase'::text, 'once'::text, 'monthly'::text, 'information'::text]))),
CHECK (((free_minutes >= 0) AND (free_minutes <= 10000))),
CHECK ((min_amount >= (0)::numeric)),
CHECK ((mode = ANY (ARRAY['add'::text, 'replace'::text]))),
CHECK (((length(TRIM(BOTH FROM name)) >= 1) AND (length(TRIM(BOTH FROM name)) <= 120))),
CHECK (((oracle_credits >= 0) AND (oracle_credits <= 10000))),
PRIMARY KEY (id),
CHECK ((rank = ANY (ARRAY['bronce'::text, 'plata'::text, 'oro'::text, 'diamante'::text]))),
CHECK (((roulette_level >= 1) AND (roulette_level <= 4))),
CHECK (((roulette_spins >= 0) AND (roulette_spins <= 100))),
CHECK ((scope = ANY (ARRAY['regular'::text, 'promotion'::text, 'all'::text])))
);

create table public.client_benefit_applications(
"id" uuid not null default gen_random_uuid(),
"client_id" uuid not null,
"payment_id" uuid,
"rule_id" uuid,
"operation_key" text not null,
"snapshot" jsonb not null,
"created_at" timestamp with time zone not null default now(),
UNIQUE (operation_key),
PRIMARY KEY (id)
);

create table public.tc_client_rank_benefits(
"rank_key" text not null,
"label" text not null,
"min_spend" numeric(12,2) not null,
"sort_order" integer not null default 0,
"is_active" boolean not null default true,
"coins_enabled" boolean not null default false,
"purchase_coins" integer not null default 0,
"roulette_enabled" boolean not null default false,
"roulette_level" smallint not null default 5,
"roulette_spins" integer not null default 1,
"daily_bonus_enabled" boolean not null default false,
"revision" integer not null default 1,
"updated_at" timestamp with time zone not null default now(),
"updated_by" uuid,
"ritual_access" boolean not null default false,
CHECK (((length(label) >= 1) AND (length(label) <= 80))),
CHECK ((min_spend > (0)::numeric)),
PRIMARY KEY (rank_key),
CHECK (((purchase_coins >= 0) AND (purchase_coins <= 1000000))),
CHECK ((rank_key ~ '^[a-z][a-z0-9_]{1,39}$'::text)),
CHECK (((roulette_level >= 1) AND (roulette_level <= 5))),
CHECK (((roulette_spins >= 1) AND (roulette_spins <= 20)))
);

create table public.tc_client_purchase_bands(
"id" uuid not null default gen_random_uuid(),
"currency" text not null,
"min_amount" numeric(12,2) not null,
"max_amount" numeric(12,2),
"roulette_level" smallint not null,
"spins" integer not null default 1,
"is_active" boolean not null default true,
"revision" integer not null default 1,
"updated_at" timestamp with time zone not null default now(),
"updated_by" uuid,
CHECK ((max_amount >= min_amount)),
CHECK ((currency = ANY (ARRAY['EUR'::text, 'USD'::text]))),
UNIQUE (currency, min_amount),
CHECK ((min_amount >= (0)::numeric)),
PRIMARY KEY (id),
CHECK (((roulette_level >= 1) AND (roulette_level <= 3))),
CHECK (((spins >= 1) AND (spins <= 20)))
);

