create table public.tc_rank_package_benefits(
"rank_key" text not null,
"package_level" smallint not null,
"enabled" boolean not null default false,
"coins" integer not null default 0,
"oracle_credits" integer not null default 0,
"roulette_level_1_spins" integer not null default 0,
"roulette_level_2_spins" integer not null default 0,
"roulette_level_3_spins" integer not null default 0,
"roulette_special_spins" integer not null default 0,
