);

create table public.tc_purchase_package_levels(
"package_source" text not null,
"package_key" text not null,
"package_label" text not null,
"package_level" smallint,
"revision" integer not null default 0,
"updated_by" uuid,
"created_at" timestamp with time zone not null default now(),
"updated_at" timestamp with time zone not null default now(),
CHECK (((package_level >= 1) AND (package_level <= 3))),
CHECK ((package_source = ANY (ARRAY['standard'::text, 'promotion'::text]))),
PRIMARY KEY (package_source, package_key)
);

create table public.tc_rank_daily_bonus_config(
"id" uuid not null default gen_random_uuid(),
"rank_key" text not null,
"enabled" boolean not null default false,
"name" text not null default 'Bono diario Diamante'::text,
"description" text not null default 'Recompensa diaria exclusiva del rango Diamante.'::text,
"coins" integer not null default 0,
"oracle_credits" integer not null default 0,
"roulette_level_1_spins" integer not null default 0,
"roulette_level_2_spins" integer not null default 0,
"roulette_level_3_spins" integer not null default 0,
"roulette_special_spins" integer not null default 0,
"revision" integer not null default 0,
"updated_by" uuid,
"created_at" timestamp with time zone not null default now(),
"updated_at" timestamp with time zone not null default now(),
CHECK (((coins >= 0) AND (coins <= 1000000))),
CHECK (((oracle_credits >= 0) AND (oracle_credits <= 100000))),
PRIMARY KEY (id),
