CHECK (((roulette_level_1_spins >= 0) AND (roulette_level_1_spins <= 10000))),
CHECK (((roulette_level_2_spins >= 0) AND (roulette_level_2_spins <= 10000))),
CHECK (((roulette_level_3_spins >= 0) AND (roulette_level_3_spins <= 10000))),
CHECK (((roulette_special_spins >= 0) AND (roulette_special_spins <= 10000)))
);

create table public.crm_paypal_orders(
"id" uuid not null,
"cliente_id" uuid not null,
"worker_id" uuid,
"environment" text not null,
"public_token" uuid not null default gen_random_uuid(),
"order_id" text,
"capture_id" text,
"approval_url" text,
"amount" numeric(10,2) not null,
"currency" text not null default 'EUR'::text,
"pack_id" text not null,
"pack_name" text not null,
"purchase_payload" jsonb not null,
"create_payload" jsonb not null,
"status" text not null default 'pending'::text,
"remote_status" text not null default 'CREATING'::text,
"last_error" text,
"payment_id" uuid,
"created_at" timestamp with time zone not null default now(),
"checked_at" timestamp with time zone,
"completed_at" timestamp with time zone,
"checkout_kind" text not null default 'crm_collection'::text,
"purchaser_auth_user_id" uuid,
CHECK (((amount > (0)::numeric) AND (amount <= (5000)::numeric))),
UNIQUE (capture_id),
CHECK ((((checkout_kind = 'crm_collection'::text) AND (worker_id IS NOT NULL) AND (purchaser_auth_user_id IS NULL)) OR ((checkout_kind = 'client_purchase'::text) AND (worker_id IS NULL) AND (purchaser_auth_user_id IS NOT NULL)))),
CHECK ((currency = 'EUR'::text)),
CHECK ((environment = ANY (ARRAY['sandbox'::text, 'live'::text]))),
UNIQUE (order_id),
PRIMARY KEY (id),
UNIQUE (public_token),
CHECK ((status = ANY (ARRAY['pending'::text, 'completed'::text, 'cancelled'::text])))
);

