);

create table public.crm_new_tarotista_gift_policy(
"id" boolean not null default true,
"activated_at" timestamp with time zone not null default clock_timestamp(),
"rank_minutes" jsonb not null default '{"oro": 12, "plata": 10, "bronce": 7, "diamante": 15, "sin_rango": 7}'::jsonb,
CHECK (id),
PRIMARY KEY (id),
CHECK (((jsonb_typeof(rank_minutes) = 'object'::text) AND (rank_minutes ?& ARRAY['sin_rango'::text, 'bronce'::text, 'plata'::text, 'oro'::text, 'diamante'::text]) AND COALESCE(((((rank_minutes ->> 'sin_rango'::text))::integer >= 1) AND (((rank_minutes ->> 'sin_rango'::text))::integer <= 60)), false) AND COALESCE(((((rank_minutes ->> 'bronce'::text))::integer >= 1) AND (((rank_minutes ->> 'bronce'::text))::integer <= 60)), false) AND COALESCE(((((rank_minutes ->> 'plata'::text))::integer >= 1) AND (((rank_minutes ->> 'plata'::text))::integer <= 60)), false) AND COALESCE(((((rank_minutes ->> 'oro'::text))::integer >= 1) AND (((rank_minutes ->> 'oro'::text))::integer <= 60)), false) AND COALESCE(((((rank_minutes ->> 'diamante'::text))::integer >= 1) AND (((rank_minutes ->> 'diamante'::text))::integer <= 60)), false)))
);

create table public.crm_new_tarotista_releases(
