CHECK ((source = ANY (ARRAY['new_worker'::text, 'explicit_rollout'::text])))
);

create table public.crm_new_tarotista_gift_uses(
"id" uuid not null default gen_random_uuid(),
"operation_id" uuid not null,
"cliente_id" uuid not null,
"tarotista_worker_id" uuid not null,
"worker_id" uuid not null,
"effective_rank" text not null,
"minutes" integer not null,
"granted_minutes" integer not null,
"previous_credit_event_id" uuid,
"benefit_event_id" uuid not null,
"rendimiento_id" uuid not null,
"request" jsonb not null,
"result" jsonb not null,
"created_at" timestamp with time zone not null default now(),
CHECK ((granted_minutes = minutes)),
UNIQUE (cliente_id, tarotista_worker_id),
CHECK ((effective_rank = ANY (ARRAY['sin_rango'::text, 'bronce'::text, 'plata'::text, 'oro'::text, 'diamante'::text]))),
CHECK (((minutes >= 1) AND (minutes <= 60))),
UNIQUE (operation_id),
PRIMARY KEY (id)
);
